#!/usr/bin/env node
/**
 * Adds the generated statistics circuit of the self layer (lib/assistant/statistics.mjs) to a base memory that imports assistant-v1.
 * Administrator action, run by the memory's loader after a build (tools/world-kb/load.mjs); a memory that already holds a statistics
 * circuit is left alone (statistics are regenerated by rebuilding the memory).
 *   node tools/assistant/memory-statistics.mjs --memory world-v1 [--root <chat data root>] [--dry-run]
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {ChatData} from '../../lib/chat-data/index.mjs';
import {BaseMemories} from '../../lib/chat-data/memories.mjs';
import {statisticsCircuit} from '../../lib/assistant/statistics.mjs';

const project = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const args = process.argv.slice(2);
const opt = (n, d) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : d; };
const id = opt('--memory', 'world-v1');
const config = JSON.parse(fs.readFileSync(path.join(project, 'config/runtime.json'), 'utf8'));
if (opt('--root', null)) config.chatData.root = path.resolve(opt('--root'));
const chatData = ChatData.open(config);
const memories = new BaseMemories({chatData, memory: config.memory});
const manifest = memories.manifest(id);
if (!(manifest.imports ?? []).some(l => l.id === 'assistant-v1')) { console.error(`${id} does not import assistant-v1`); process.exit(2); }
if (memories.circuits(id).some(c => /-memory-statistics\.sop$/.test(c.name))) { console.log(JSON.stringify({id, skipped: 'a statistics circuit is present; rebuild the memory to regenerate it'})); process.exit(0); }
const lexicon = chatData.lexicons.get(memories.layeredCircuits(id), {provenance: `base-memory:${id}`});
const text = statisticsCircuit({lexicon, manifest, stats: memories.stats(id), layers: (manifest.imports ?? []).map(l => l.name)});
if (args.includes('--dry-run')) { process.stdout.write(text); process.exit(0); }
const added = memories.addKnowledge(id, {circuits: [{name: 'memory-statistics', text}], approvedBy: opt('--approved-by', 'memory-statistics'), reason: 'generated self-layer statistics (assistant-v1)', source: 'tools/assistant/memory-statistics.mjs'});
console.log(JSON.stringify({id, added: added.added.map(a => ({file: a.file, wires: a.wires, facts: a.ingest.facts_ingested}))}));
